import{_ as t,o,c as a,ae as i}from"./chunks/framework.BONZgKEB.js";const g=JSON.parse('{"title":"Scoring Workflow & Matches","description":"","frontmatter":{},"headers":[],"relativePath":"guide/scoring-workflow.md","filePath":"guide/scoring-workflow.md"}'),r={name:"guide/scoring-workflow.md"};function s(n,e,l,c,h,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="scoring-workflow-matches" tabindex="-1">Scoring Workflow &amp; Matches <a class="header-anchor" href="#scoring-workflow-matches" aria-label="Permalink to &quot;Scoring Workflow &amp; Matches&quot;">​</a></h1><p>This guide covers how athletes and referees input and track scores during both the Qualification and Elimination rounds using the digital scoresheet.</p><h2 id="_1-accessing-the-scoresheet" tabindex="-1">1. Accessing the Scoresheet <a class="header-anchor" href="#_1-accessing-the-scoresheet" aria-label="Permalink to &quot;1. Accessing the Scoresheet&quot;">​</a></h2><p>During an active competition, authorized users (Athletes and Referees) can access the scoresheet directly from their device.</p><ol><li>Navigate to the active <strong>Competition</strong>.</li><li>Depending on the current phase, select either <strong>Qualification</strong> or <strong>Elimination</strong>.</li><li>Find your assigned Target or Match and click <strong>Enter Scores</strong>.</li></ol><blockquote><p><strong>Note:</strong> Only the assigned athlete or an official event referee can input scores for a specific target.</p></blockquote><h2 id="_2-qualification-scoring" tabindex="-1">2. Qualification Scoring <a class="header-anchor" href="#_2-qualification-scoring" aria-label="Permalink to &quot;2. Qualification Scoring&quot;">​</a></h2><p>The Qualification view provides a digital replica of a traditional archery scorecard.</p><h3 id="entering-end-scores" tabindex="-1">Entering End Scores <a class="header-anchor" href="#entering-end-scores" aria-label="Permalink to &quot;Entering End Scores&quot;">​</a></h3><ol><li>The scorecard is divided into <strong>Ends</strong> (usually 3 or 6 arrows per end).</li><li>Enter the value of each arrow shot in descending order (e.g., 10, 9, 9, 8, 8, 7).</li><li>The system will automatically calculate the: <ul><li><strong>End Total:</strong> Sum of the arrows in the current end.</li><li><strong>Running Total:</strong> Cumulative score for the entire round.</li><li><strong>10s and Xs:</strong> The system automatically tallies the number of 10s and inner-10s (Xs) for tie-breaking purposes.</li></ul></li></ol><h3 id="live-leaderboard" tabindex="-1">Live Leaderboard <a class="header-anchor" href="#live-leaderboard" aria-label="Permalink to &quot;Live Leaderboard&quot;">​</a></h3><p>As scores are submitted end-by-end, the <strong>Live Leaderboard</strong> updates automatically. This allows spectators, coaches, and athletes to see real-time rankings without waiting for the end of the tournament.</p><h2 id="_3-elimination-scoring-matches" tabindex="-1">3. Elimination Scoring (Matches) <a class="header-anchor" href="#_3-elimination-scoring-matches" aria-label="Permalink to &quot;3. Elimination Scoring (Matches)&quot;">​</a></h2><p>Scoring an elimination match differs depending on the bow style (Recurve vs. Compound). The application automatically adjusts the scoring interface based on the competition rules.</p><h3 id="recurve-set-system" tabindex="-1">Recurve: Set System <a class="header-anchor" href="#recurve-set-system" aria-label="Permalink to &quot;Recurve: Set System&quot;">​</a></h3><p>Recurve matches use the Set System.</p><ol><li>Athletes shoot sets of 3 arrows.</li><li>Enter the arrow values for both athletes.</li><li>The system calculates the set total. <ul><li>The athlete with the higher set score receives <strong>2 Set Points</strong>.</li><li>If tied, both receive <strong>1 Set Point</strong>.</li></ul></li><li>The first athlete to reach <strong>6 Set Points</strong> wins the match.</li></ol><h3 id="compound-cumulative-scoring" tabindex="-1">Compound: Cumulative Scoring <a class="header-anchor" href="#compound-cumulative-scoring" aria-label="Permalink to &quot;Compound: Cumulative Scoring&quot;">​</a></h3><p>Compound matches use cumulative scoring.</p><ol><li>Athletes shoot ends of 3 arrows.</li><li>Enter the arrow values for both athletes.</li><li>The system maintains a running total.</li><li>After the designated number of ends (usually 5 ends, totaling 15 arrows), the athlete with the highest total score wins the match.</li></ol><h3 id="tie-breakers-shoot-offs" tabindex="-1">Tie-Breakers (Shoot-offs) <a class="header-anchor" href="#tie-breakers-shoot-offs" aria-label="Permalink to &quot;Tie-Breakers (Shoot-offs)&quot;">​</a></h3><p>If a match is tied at the end of regulation (e.g., 5-5 in Set Points, or 145-145 in Cumulative), the system will prompt a <strong>Shoot-off</strong>.</p><ol><li>Each athlete shoots a single arrow.</li><li>Enter the score.</li><li>If the scores are identical (e.g., both shoot a 10), the referee must measure the distance to the center. You can mark which arrow is closer in the system to determine the winner.</li></ol>',23)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
